// Generate clean, secure random temporary password (e.g. Auto#K3x9W2pQ)
function generateTempPassword() {
  const upper = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
  const lower = 'abcdefghjkmnpqrstuvwxyz';
  const digits = '23456789';
  let rand = '';
  for (let i = 0; i < 3; i++) rand += upper[Math.floor(Math.random() * upper.length)];
  for (let i = 0; i < 3; i++) rand += lower[Math.floor(Math.random() * lower.length)];
  for (let i = 0; i < 3; i++) rand += digits[Math.floor(Math.random() * digits.length)];
  rand = rand.split('').sort(() => 0.5 - Math.random()).join('');
  return 'Auto#' + rand;
}

const body = $input.first().json.body || {};

const firstName = (body.firstName || '').trim();
const lastName = (body.lastName || '').trim();
const email = (body.email || '').trim().toLowerCase();
const personalEmail = (body.personalEmail || '').trim().toLowerCase();
const phone = (body.phone || '').trim();
const designation = (body.designation || '').trim();
const role = (body.role || 'EMPLOYEE').trim().toUpperCase();
const employmentType = (body.employmentType || 'Full-time').trim();
const workLocation = (body.workLocation || 'Chinar Park, Teghoria, Kolkata (In-Office)').trim();
const customId = body.customId ? body.customId.trim() : '';
const salary = parseFloat(body.salary) || 0;

// If client sends raw password, use it; otherwise generate random temporary password
let rawPassword = (body.password || '').trim();
let isAutoGenerated = false;
if (!rawPassword) {
  rawPassword = generateTempPassword();
  isAutoGenerated = true;
}

// Joining date: formatted as YYYY-MM-DD
let joiningDate = body.joiningDate ? body.joiningDate.trim() : '';
if (!joiningDate) {
  const now = new Date();
  joiningDate = now.toISOString().split('T')[0];
}

// 1. Validation
if (!firstName || !lastName || !email || !phone || !designation) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: 'Missing required fields: firstName, lastName, email, phone, and designation are required.'
    }
  }];
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(email)) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: 'Invalid email address format.'
    }
  }];
}

return [{
  json: {
    valid: true,
    firstName,
    lastName,
    email,
    personalEmail,
    escapedEmail: email.replace(/'/g, "''"),
    rawPassword: rawPassword.replace(/'/g, "''"),
    plainPasswordForEmail: rawPassword,
    isAutoGenerated,
    phone,
    designation,
    salary,
    role: (role === 'ADMIN' ? 'ADMIN' : 'EMPLOYEE'),
    employmentType,
    workLocation,
    joiningDate,
    customId
  }
}];

const validatedData = $('Code - Validate Input & Generate Password').first().json;
const items = $input.all();
const dbRow = (items.length > 0 && items[0].json) ? items[0].json : {};

const emailCount = parseInt(dbRow.email_count || '0', 10);
if (emailCount > 0) {
  return [{
    json: {
      success: false,
      statusCode: 409,
      error: "An employee with email '" + validatedData.email + "' already exists."
    }
  }];
}

// Generate next ID like EMP-001, EMP-025, etc. if not provided
let employeeId = validatedData.customId;
if (!employeeId) {
  const maxNum = parseInt(dbRow.max_emp_num || '0', 10);
  const nextNum = Math.max(maxNum + 1, 25);
  employeeId = 'EMP-' + String(nextNum).padStart(3, '0');
}

return [{
  json: {
    success: true,
    employeeId: employeeId,
    firstName: validatedData.firstName,
    lastName: validatedData.lastName,
    email: validatedData.email,
    personalEmail: validatedData.personalEmail,
    rawPassword: validatedData.rawPassword,
    plainPasswordForEmail: validatedData.plainPasswordForEmail,
    isAutoGenerated: validatedData.isAutoGenerated,
    phone: validatedData.phone,
    designation: validatedData.designation,
    joiningDate: validatedData.joiningDate,
    employmentType: validatedData.employmentType,
    workLocation: validatedData.workLocation,
    role: validatedData.role,
    salary: validatedData.salary
  }
}];
